#if UNITY_EDITOR
using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Security.Cryptography;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
using UnityEditor;
using UnityEngine;
using UnityEngine.UI;
namespace LastRail.Tests.EditMode {
 public class KyleApprovedDeliveryTests {
  const string Root="Assets/_LASTRAIL/UI/CombatAnimations/KyleDeliveryV01";
  const string Source="D:/Project/LASTRAIL/QA/DirectionImpact-20260921/eve-combat-v01/kyle-delivery-v01/";
  static Type Builder=>AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("LastRail.Editor.KyleApprovedDeliveryBuilder")).FirstOrDefault(t=>t!=null);
  static string Hash(byte[] b){using var s=SHA256.Create();return BitConverter.ToString(s.ComputeHash(b)).Replace("-","").ToLowerInvariant();}
  readonly Dictionary<string,string> existing=new Dictionary<string,string>();
  [OneTimeSetUp]public void Import(){Assert.IsNotNull(Builder);foreach(var dir in new[]{"Assets/_LASTRAIL/UI/CombatAnimations/Operators","Assets/_LASTRAIL/UI/CombatAnimations/Clips/Operators","Assets/_LASTRAIL/UI/CombatAnimations/Animators/Operators"})if(Directory.Exists(dir))foreach(var p in Directory.GetFiles(dir,"*",SearchOption.AllDirectories))existing.Add(p,Hash(File.ReadAllBytes(p)));Builder.GetMethod("Build").Invoke(null,null);}
  [Test]public void ApprovedDeliveryHasScopedImporter()=>Assert.IsNotNull(Builder);
  [Test]public void EveryImportedFrameHasExactlyApprovedBytesAndSingleUncompressedFullCanvasSprite(){var m=JObject.Parse(File.ReadAllText(Source+"manifest.json"));int count=0;foreach(var row in (JArray)m["inventory"]){var relative=(string)row["path"];if(!(relative.StartsWith("actors/")||relative.StartsWith("fx/tool/"))||!relative.EndsWith(".png"))continue;string p=Root+"/Sources/"+relative;Assert.AreEqual((string)row["sha256"],Hash(File.ReadAllBytes(p)));var i=(TextureImporter)AssetImporter.GetAtPath(p);Assert.AreEqual(TextureImporterType.Sprite,i.textureType);Assert.AreEqual(SpriteImportMode.Single,i.spriteImportMode);Assert.IsFalse(i.mipmapEnabled);Assert.IsTrue(i.sRGBTexture);Assert.AreEqual(TextureWrapMode.Clamp,i.wrapMode);Assert.AreEqual(FilterMode.Bilinear,i.filterMode);var settings=new TextureImporterSettings();i.ReadTextureSettings(settings);Assert.AreEqual(SpriteMeshType.FullRect,settings.spriteMeshType);Assert.AreEqual(TextureImporterCompression.Uncompressed,i.textureCompression);Assert.GreaterOrEqual(i.maxTextureSize,2048);Assert.IsNotNull(AssetDatabase.LoadAssetAtPath<Sprite>(p));count++;}Assert.AreEqual(105,count);}
  [Test]public void EightVariableExposureClipsPreserveTerminalHoldAndIdleLoop(){Assert.AreEqual(8,Directory.GetFiles(Root+"/Clips","*.anim").Length);var m=JObject.Parse(File.ReadAllText(Source+"manifest.json"));foreach(int d in Enumerable.Range(1,4))foreach(string motion in new[]{"idle","attack"}){var clip=AssetDatabase.LoadAssetAtPath<AnimationClip>(Root+"/Clips/d"+d+"_"+motion+".anim");var binding=AnimationUtility.GetObjectReferenceCurveBindings(clip).Single();Assert.AreEqual(typeof(Image),binding.type);var keys=AnimationUtility.GetObjectReferenceCurve(clip,binding);Assert.AreEqual(13,keys.Length);float t=0;for(int n=0;n<12;n++){Assert.AreEqual(t,keys[n].time,1e-5);Assert.AreEqual(AssetDatabase.LoadAssetAtPath<Sprite>(Root+"/Sources/actors/d"+d+"/"+motion+"-"+(n+1).ToString("00")+".png"),keys[n].value);t+=(int)m[motion+"_durations_ms"][n]/1000f;}Assert.AreEqual(motion=="idle"?1.44f:1.04f,clip.length,1e-5);Assert.AreEqual(t-.001f,keys[12].time,1e-5);Assert.AreSame(keys[11].value,keys[12].value);Assert.AreEqual(motion=="idle",AnimationUtility.GetAnimationClipSettings(clip).loopTime);if(motion=="attack"){Assert.AreEqual(.38f,keys[5].time,1e-5);Assert.AreSame(keys[11].value,keys[12].value);}Assert.AreEqual(0,AnimationUtility.GetAnimationEvents(clip).Length,"No gameplay damage/fire policy from art clip");}}
  [Test]public void AllDirectionsUseFixedFootPivotAndOriginalCanvasWithEqualVisibleHeight(){var m=JObject.Parse(File.ReadAllText(Source+"manifest.json"));var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(Root+"/KyleFourDirectionFixture.prefab");Assert.IsNotNull(prefab);foreach(var row in (JArray)m["directions"]){int d=(int)row["direction"];var r=prefab.transform.Find("Direction"+d).GetComponent<RectTransform>();Assert.AreEqual((float)row["foot_anchor_normalized"][0],r.pivot.x,1e-6);Assert.AreEqual(1-(float)row["foot_anchor_normalized"][1],r.pivot.y,1e-6);float canvas=(float)row["canvas"][1],bbox=(float)row["idle_bbox_alpha128"][3]-(float)row["idle_bbox_alpha128"][1];Assert.AreEqual(88.5248f,r.sizeDelta.y*bbox/canvas,1e-4);Assert.AreEqual(Vector3.one,r.localScale);foreach(string motion in new[]{"idle","attack"})for(int n=1;n<=12;n++){var s=AssetDatabase.LoadAssetAtPath<Sprite>(Root+"/Sources/actors/d"+d+"/"+motion+"-"+n.ToString("00")+".png");Assert.AreEqual(canvas,s.rect.height);Assert.AreEqual(r.pivot.y,s.pivot.y/s.rect.height,1e-6);Assert.AreEqual(r.pivot.x,s.pivot.x/s.rect.width,1e-6);}}}
  [Test]public void DirectionAdapterAndIndependentFxKeepExplicitRightFacingAndAuthorityBoundary(){var b=JObject.Parse(File.ReadAllText(Root+"/presentation-binding.json"));CollectionAssert.AreEqual(new[]{150f,-180f,-150f,90f},((JArray)b["directionAdapter"]).Select(d=>(float)d["rotationYUpDegrees"]));var sprite=AssetDatabase.LoadAssetAtPath<Sprite>(Root+"/Sources/fx/tool/projectile.png");Assert.AreEqual(new Vector2(22,12),sprite.rect.size);Assert.AreEqual(8,((JArray)b["impactFrames"]).Count);foreach(var path in (JArray)b["impactFrames"]){var impact=AssetDatabase.LoadAssetAtPath<Sprite>(Root+"/"+(string)path);Assert.AreEqual(new Vector2(192,192),impact.rect.size);Assert.AreEqual(new Vector2(96,96),impact.pivot);}Assert.AreEqual(380,(int)b["fireAttackMs"]);Assert.AreEqual("IMPORT_AND_EXPLICIT_2D_FIXTURE_NOT_GAMEPLAY_CONNECTION",(string)b["scope"]);}
  [Test]public void ExistingAllOperatorResourcesAndHitDownSkillRemainByteIdentical(){Assert.Greater(existing.Count,0);foreach(var row in existing)Assert.AreEqual(row.Value,Hash(File.ReadAllBytes(row.Key)),row.Key);}
 }
}
#endif